129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
132	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already
133	        // seen, return the owner originally created under it (200) rather than creating a
134	        // duplicate. The key is remembered only after a successful create below.
135	        String idempotencyKey = currentIdempotencyKey();
136	        if (idempotencyKey != null) {
137	            Integer existingId = idempotentCreates.get(idempotencyKey);
138	            if (existingId != null) {
139	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
140	                if (existingOwner != null) {
141	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
142	                }
143	            }
144	        }
145	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
146	        if (normalizedTelephone == null) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
153	        // The owner must supply an address in EITHER form: a non-blank structured
154	        // 'addressLine1' or the flat 'address'. getAddress() prefers the structured
155	        // fields (composing line 1 with an optional line 2) and falls back to the flat
156	        // value; a blank result means neither form was provided. The composed value is
157	        // written back so the persisted flat 'address' stays consistent with it.
158	        String composedAddress = owner.getAddress();
159	        if (composedAddress == null || composedAddress.isBlank()) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        owner.setAddress(composedAddress);
163	        owner.setTelephone(normalizedTelephone);
164	        if (!owner.isPostcodeValidForCity()) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        // The household id is deterministic: it is derived purely from the owner's
168	        // (last name, postcode), so every owner at the same last name and postcode resolves
169	        // to the same value. It is assigned up front, before any duplicate detection, so the
170	        // identity key and the household check below both key off it.
171	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
172	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
173	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
174	        // identityKey (telephone|email|householdId) equals an existing owner's. With the
175	        // household id now computed up front, two members of one household still differ here
176	        // whenever their telephone or email differs, and so are both allowed.
177	        String identityKey = owner.getIdentityKey();
178	        if (this.clinicService.findAllOwners().stream()
179	            .filter(existing -> !existing.isDeleted())
180	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
181	            return new ResponseEntity<>(HttpStatus.CONFLICT);
182	        }
183	        // Household duplicate: because the household is keyed on (last name, postcode), any
184	        // existing owner sharing this computed household id is the same household. A second
185	        // such owner is rejected as a household duplicate (409) unless it explicitly declares
186	        // 'sharesHousehold', which now only bypasses this block (the link is no longer created
187	        // here — the id is computed).
188	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
189	        if (!householdMembers.isEmpty() && !sharesHousehold) {
190	            return new ResponseEntity<>(HttpStatus.CONFLICT);
191	        }
192	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
193	            return new ResponseEntity<>(HttpStatus.CONFLICT);
194	        }
195	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
196	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
197	        }
198	        LocalDate effectiveDate =
199	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
200	        LocalDate registrationDate = toBusinessDay(effectiveDate);
201	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
202	        if (ownersRegisteredToday >= 100) {
203	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
204	        }
205	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
206	        HttpHeaders headers = new HttpHeaders();
207	        owner.setRegistrationDate(registrationDate);
208	        owner.setCustomerCode(customerCode(owner));
209	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
210	        owner.setBulkSignupWarning(bulkSignupWarning);
211	        // The household size (an input to the membership computation) keys off the computed
212	        // household id: this owner plus everyone already sharing it.
213	        owner.setHouseholdSize(householdMembers.size() + 1);
214	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
215	        // duplicate, so only a non-declared create is scored. In practice a non-declared owner
216	        // sharing an existing owner's last name and postcode is already rejected above as a
217	        // household duplicate, so this now only ever confirms the owner is not a duplicate.
218	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
219	        owner.setPossibleDuplicate(possibleDuplicate != null);
220	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
221	        this.clinicService.saveOwner(owner);
222	        if (idempotencyKey != null) {
223	            idempotentCreates.put(idempotencyKey, owner.getId());
224	        }
225	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
226	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
227	            owner.getMembershipNumber());
228	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
229	        headers.setLocation(UriComponentsBuilder.newInstance()
230	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
231	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
232	    }
