255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Transactional
257	    @Override
258	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner == null) {
261	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	        }
263	        // Soft-delete: retain the row and flag it deleted rather than removing it. The owner
264	        // remains readable via GET, and is subsequently ignored by the create endpoint's
265	        // duplicate and identity checks.
266	        owner.setDeleted(true);
267	        this.clinicService.saveOwner(owner);
268	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
269	    }
