323	    /**
324	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
325	     * stripped. When a leading {@code '+'} and country code are present they are kept;
326	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
327	     * is dropped from the national digits. The result must be a {@code '+'} followed
328	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
329	     * is returned to signal a bad request.
330	     */
331	    /**
332	     * Build the customer code for a newly created owner, formatted
333	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
334	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
335	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
336	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
337	     * with its last name. This identity carries no sequence number.
338	     */
339	    private String customerCode(Owner owner) {
340	        String region = owner.getLocality();
341	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
342	        String base = region + "-" + hash8;
343	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
344	            .map(Owner::getCustomerCode)
345	            .filter(java.util.Objects::nonNull)
346	            .collect(java.util.stream.Collectors.toSet());
347	        if (!existing.contains(base)) {
348	            return base;
349	        }
350	        int n = 2;
351	        while (existing.contains(base + "-" + n)) {
352	            n++;
353	        }
354	        return base + "-" + n;
355	    }
356	
357	    /**
358	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
359	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
360	     * treated as empty when {@code null}), already in their normalized forms.
361	     */
362	    private String customerCodeHash(String telephone, String lastName) {
363	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
364	        try {
365	            byte[] digest = MessageDigest.getInstance("SHA-256")
366	                .digest(key.getBytes(StandardCharsets.UTF_8));
367	            StringBuilder sb = new StringBuilder();
368	            for (int i = 0; i < 4; i++) {
369	                sb.append(String.format("%02X", digest[i]));
370	            }
371	            return sb.toString();
372	        }
373	        catch (NoSuchAlgorithmException e) {
374	            throw new IllegalStateException(e);
375	        }
376	    }
377	
378	    /**
379	     * Count the existing owners whose city matches the given one, compared after
380	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
381	     * cap: a city that already holds this many owners is at capacity.
382	     */
383	    private long countOwnersInCity(String city) {
384	        String normalizedCity = normalizeForHousehold(city);
385	        return this.clinicService.findAllOwners().stream()
386	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
387	            .count();
388	    }
389	
390	    /**
391	     * Count the existing owners whose registration date falls on the given day. Used to
392	     * enforce the per-day create limit: once this many owners have been registered today,
393	     * the day is at capacity and further creates are rejected.
394	     */
395	    private long countOwnersRegisteredOn(LocalDate day) {
396	        return this.clinicService.findAllOwners().stream()
397	            .filter(existing -> day.equals(existing.getRegistrationDate()))
398	            .count();
399	    }
400	
401	    /**
402	     * The fixed public holidays that the business-day roll skips. A registration date
403	     * landing on one of these is treated like a weekend and advanced to the next
404	     * non-holiday business day.
405	     */
406	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
407	        LocalDate.parse("2026-01-01"),
408	        LocalDate.parse("2026-01-26"),
409	        LocalDate.parse("2026-04-25"),
410	        LocalDate.parse("2026-12-25"),
411	        LocalDate.parse("2026-12-28"));
412	
413	    /**
414	     * Roll a registration date forward to the next business day: a date falling on a
415	     * Saturday, Sunday or listed public holiday is advanced one day at a time until it
416	     * lands on a non-holiday weekday, while a plain weekday is returned unchanged.
417	     */
418	    private LocalDate toBusinessDay(LocalDate date) {
419	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
420	            date = date.plusDays(1);
421	        }
422	        return date;
423	    }
424	
425	    private static boolean isWeekend(LocalDate date) {
426	        DayOfWeek dayOfWeek = date.getDayOfWeek();
427	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY;
428	    }
429	
430	    /**
431	     * Find the existing owners that already belong to the same household as the given
432	     * computed household id. Because the household id is derived deterministically from
433	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
434	     * that last name and postcode.
435	     */
436	    private List<Owner> findHouseholdMembers(String householdId) {
437	        if (householdId == null) {
438	            return List.of();
439	        }
440	        return this.clinicService.findAllOwners().stream()
441	            .filter(existing -> !existing.isDeleted())
442	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
443	            .toList();
444	    }
445	
446	    /**
447	     * Find an existing owner that this new owner softly duplicates: one sharing the same
448	     * last name (compared case-insensitively after whitespace normalization) and the same
449	     * postcode, but with a different telephone. Returns the lowest-id such owner, or
450	     * {@code null} when the new owner has no postcode or no soft match exists. Owners
451	     * whose telephone equals the new owner's are excluded, as those are governed by the
452	     * hard-duplicate (identityKey) check rather than this soft match.
453	     */
454	    private Owner findPossibleDuplicate(Owner owner) {
455	        String postcode = owner.getPostcode();
456	        if (postcode == null) {
457	            return null;
458	        }
459	        String normalizedLastName = normalizeForHousehold(owner.getLastName());
460	        String telephone = owner.getTelephone();
461	        return this.clinicService.findAllOwners().stream()
462	            .filter(existing -> !existing.isDeleted())
463	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
464	                && postcode.equals(existing.getPostcode())
465	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
466	            .min(java.util.Comparator.comparing(Owner::getId))
467	            .orElse(null);
468	    }
469	
470	    /**
471	     * Count the existing owners that already share both the given first and last
472	     * name, compared case-insensitively. Used to populate an owner's namesake count
473	     * at creation time, reflecting how many owners with the same name existed before
474	     * this one was created.
475	     */
476	    private int countNamesakes(String firstName, String lastName) {
477	        String normalizedFirstName = normalizeName(firstName);
478	        String normalizedLastName = normalizeName(lastName);
479	        return (int) this.clinicService.findAllOwners().stream()
480	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
481	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
482	            .count();
483	    }
484	
485	    private String normalizeName(String value) {
486	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
487	    }
488	
489	    /**
490	     * Build the deterministic identifier shared by all owners of one household: the first
491	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
492	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
493	     * name and postcode resolves to the same value regardless of creation order.
494	     */
495	    private String householdId(String lastName, String postcode) {
496	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
497	        try {
498	            byte[] digest = MessageDigest.getInstance("SHA-256")
499	                .digest(key.getBytes(StandardCharsets.UTF_8));
500	            StringBuilder sb = new StringBuilder();
501	            for (int i = 0; i < 6; i++) {
502	                sb.append(String.format("%02x", digest[i]));
503	            }
504	            return sb.toString();
505	        }
506	        catch (NoSuchAlgorithmException e) {
507	            throw new IllegalStateException(e);
508	        }
509	    }
510	
511	    private String normalizeForHousehold(String value) {
512	        if (value == null) {
513	            return "";
514	        }
515	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
516	    }
517	
518	    /** True when the email's domain is on the disposable-provider blocklist. */
519	    private boolean isDisposableEmailDomain(String email) {
520	        if (email == null) {
521	            return false;
522	        }
523	        int at = email.lastIndexOf('@');
524	        if (at < 0 || at == email.length() - 1) {
525	            return false;
526	        }
527	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
528	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
