532	     * Read the {@code Idempotency-Key} header from the current request, or {@code null}
533	     * when it is absent or blank (the generated API signature does not expose it, so it is
534	     * pulled from the bound request attributes).
535	     */
536	    private String currentIdempotencyKey() {
537	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
538	            return null;
539	        }
540	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
541	        return (key == null || key.isBlank()) ? null : key;
542	    }
