544	    private String normalizeTelephone(String telephone) {
545	        if (telephone == null) {
546	            return null;
547	        }
548	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
549	        String digits;
550	        if (cleaned.startsWith("+")) {
551	            digits = cleaned.substring(1);
552	        } else {
553	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
554	            digits = "61" + national;
555	        }
556	        if (!digits.matches("[0-9]{8,15}")) {
557	            return null;
558	        }
559	        if (!hasValidNationalLength(digits)) {
560	            return null;
561	        }
562	        return "+" + digits;
563	    }
564	
565	    /**
566	     * Validate the national-number length of an E.164 number (the digits, without the
567	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
568	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
569	     * codes without a known rule are accepted as-is.
570	     */
571	    private boolean hasValidNationalLength(String digits) {
572	        if (digits.startsWith("61")) {
573	            return digits.length() - 2 == 9;
574	        }
575	        if (digits.startsWith("1")) {
576	            return digits.length() - 1 == 10;
577	        }
578	        return true;
579	    }
